open] summary .sf-icon{transform:rotate(45deg)}.sf-premium-guide__return{display:flex;align-items:center;gap:8px;margin-top:20px;padding:13px;border-radius:12px;background:#f4f7f1;font-size:11px;line-height:18px;color:#87997d}.sf-premium-guide__return>.sf-icon{flex-shrink:0}
</style>
